"""Roman numeral conversion (1..3999)."""


def to_roman(n: int) -> str:
    """Convert an integer 1..3999 to a standard Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"integer expected, got {type(n).__name__}")
    if not (1 <= n <= 3999):
        raise ValueError(f"number must be between 1 and 3999, got {n}")

    _MAP = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    parts = []
    for value, numeral in _MAP:
        count, n = divmod(n, value)
        parts.append(numeral * count)
    return "".join(parts)


# Pre-built reverse map for from_roman validation / decoding.
_REVERSE_MAP = sorted(_MAP, key=lambda x: x[0], reverse=True)


def from_roman(s: str) -> int:
    """Convert a standard Roman numeral string to an integer."""
    if not isinstance(s, str) or not s:
        raise ValueError("non-string or empty input")

    # Valid symbols
    VALID = set("IVXLCDM")
    if not all(c in VALID for c in s):
        raise ValueError(f"invalid character in '{s}'")

    # Quick structural checks before full parse
    # Must not contain more than three consecutive identical I/X/C/M
    import re
    if re.search(r'(.)\1{3,}', s):
        raise ValueError(f"repetition too long in '{s}'")

    # V, L, D may never repeat at all
    if re.search(r'[VLD]{2,}', s):
        raise ValueError(f"repeated non-I symbol in '{s}'")

    # Full decode using greedy largest-first matching on the canonical map
    total = 0
    i = 0
    while i < len(s):
        matched = False
        for value, numeral in _REVERSE_MAP:
            if s[i:i + len(numeral)] == numeral:
                total += value
                i += len(numeral)
                matched = True
                break
        if not matched:
            raise ValueError(f"unparseable remainder starting at index {i} in '{s}'")

    # Round-trip check: encode it back and compare
    if to_roman(total) != s:
        raise ValueError(f"'{s}' is not well-formed (round-trip failed)")

    return total

